// ## src/utils/listQuery.js
const escapeRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

export async function listQuery(Model, query, { sortable = [], filterable = [], searchField = 'name' } = {}) {
  const page = Math.max(parseInt(query.page) || 1, 1)
  const limit = Math.min(Math.max(parseInt(query.limit) || 10, 1), 100)

  const filter = {}
  for (const key of filterable) if (typeof query[key] === 'string') filter[key] = query[key]
  if (query.minPrice || query.maxPrice) {
    filter.price = {}
    if (query.minPrice) filter.price.$gte = Number(query.minPrice)
    if (query.maxPrice) filter.price.$lte = Number(query.maxPrice)
  }
  if (typeof query.search === 'string' && query.search) {
    filter[searchField] = { $regex: escapeRegex(query.search), $options: 'i' }
  }

  const sort = String(query.sort ?? '-createdAt')
    .split(',')
    .filter((s) => sortable.includes(s.replace(/^-/, '')))
    .join(' ') || '-createdAt'

  const select = typeof query.fields === 'string' ? query.fields.split(',').join(' ') : ''

  const [data, total] = await Promise.all([
    Model.find(filter).sort(sort).select(select).skip((page - 1) * limit).limit(limit).lean(),
    Model.countDocuments(filter),
  ])
  return { data, meta: { page, limit, total, totalPages: Math.ceil(total / limit) } }
}

