import mongoose from 'mongoose'
import { Router } from 'express'

const orderSchema = new mongoose.Schema({
  user: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  items: [{ name: String, price: Number, qty: Number }],
  status: { type: String, enum: ['pending', 'paid', 'shipped'], default: 'pending' },
}, { timestamps: true })
const Order = mongoose.model('Order', orderSchema)

const router = Router()

// revenue per month for paid orders
router.get('/stats/monthly', async (req, res) => {
  const stats = await Order.aggregate([
    { $match: { status: 'paid' } },
    { $unwind: '$items' },
    { $group: {
        _id: { year: { $year: '$createdAt' }, month: { $month: '$createdAt' } },
        revenue: { $sum: { $multiply: ['$items.price', '$items.qty'] } },
        orders: { $addToSet: '$_id' },
    } },
    { $project: { _id: 0, year: '$_id.year', month: '$_id.month', revenue: 1, orderCount: { $size: '$orders' } } },
    { $sort: { year: 1, month: 1 } },
  ])
  res.json(stats)
})

// orders of one user with user details joined
router.get('/by-user/:userId', async (req, res) => {
  const userId = new mongoose.Types.ObjectId(req.params.userId)
  const orders = await Order.aggregate([
    { $match: { user: userId } },
    { $lookup: { from: 'users', localField: 'user', foreignField: '_id', as: 'user' } },
    { $unwind: '$user' },
    { $project: { status: 1, items: 1, 'user.name': 1, 'user.email': 1 } },
  ])
  res.json(orders)
})

export default router

